use crate::domain::{
    models::{
        declaration_resolution::{ComparisonRow, ScoredPair, ScoredPairs, ScoringInput},
        entity_ingestion::EntityIngestionError,
    },
    repositories::declaration_resolution::FunderScorer,
};
use polars::prelude::*;
use serde::Serialize;
use std::sync::Arc;
use weldrs::{
    comparison::{Comparison, ComparisonBuilder},
    comparison_vectors::compute_comparison_vectors,
    predict::predict_direct,
};

mod blocking;
#[cfg(test)]
mod tests;

use blocking::{Candidate, CandidateRule, bounded_candidates};

/// Native scoring adapter for bounded funder profile candidates.
pub struct WeldrsFunderScorer {
    model: Arc<NativeModel>,
}

#[derive(Serialize)]
struct NativeModel {
    version: u32,
    prior: f64,
    comparisons: [Comparison; 2],
    blocking: [CandidateRule; 5],
    missing_address: MissingAddressPolicy,
}
#[derive(Serialize)]
enum MissingAddressPolicy {
    EitherMissingIsNeutral,
}
#[derive(Serialize)]
enum DistanceEngine {
    WeldrsSimdUtf8Bytes,
}
#[derive(Serialize)]
struct NativeProvenance<'a> {
    model: &'a NativeModel,
    model_version: &'static str,
    weldrs_version: &'static str,
    runtime: NativeRuntime,
    calibrated: bool,
}
#[derive(Serialize)]
struct NativeRuntime {
    library: &'static str,
    adapter_version: u32,
    distance_engine: DistanceEngine,
}

fn error(message: impl std::fmt::Display) -> EntityIngestionError {
    EntityIngestionError::DataError(format!("native funder scorer: {message}"))
}

impl WeldrsFunderScorer {
    /// Constructs the immutable frozen funder model.
    ///
    /// # Errors
    /// Returns an error if comparison construction or frozen parameters are invalid.
    pub fn new() -> Result<Self, EntityIngestionError> {
        let mut name = ComparisonBuilder::new("name")
            .null_level()
            .exact_match_level()
            .levenshtein_level(2)
            .else_level()
            .build()
            .map_err(error)?;
        let mut address = ComparisonBuilder::new("address")
            .null_level()
            .exact_match_level()
            .else_level()
            .build()
            .map_err(error)?;
        set_parameters(&mut name, &[(0.95, 0.001), (0.04, 0.009), (0.01, 0.99)])?;
        set_parameters(&mut address, &[(0.9, 0.00001), (0.1, 0.99999)])?;
        Ok(Self {
            model: Arc::new(NativeModel {
                version: 2,
                prior: 0.0001,
                comparisons: [name, address],
                blocking: CandidateRule::ALL,
                missing_address: MissingAddressPolicy::EitherMissingIsNeutral,
            }),
        })
    }
}

fn set_parameters(
    comparison: &mut Comparison,
    parameters: &[(f64, f64)],
) -> Result<(), EntityIngestionError> {
    let levels = comparison.non_null_levels_mut();
    if levels.len() != parameters.len() {
        return Err(error("incomplete comparison parameters"));
    }
    for (level, &(m, u)) in levels.into_iter().zip(parameters) {
        if [m, u]
            .into_iter()
            .any(|p| !p.is_finite() || p <= 0.0 || p >= 1.0)
        {
            return Err(error("invalid comparison probability"));
        }
        level.m_probability = Some(m);
        level.u_probability = Some(u);
    }
    Ok(())
}

impl FunderScorer for WeldrsFunderScorer {
    async fn score(&self, input: &ScoringInput) -> Result<ScoredPairs, EntityIngestionError> {
        let rows = input.rows.clone();
        let budget = input.candidate_budget;
        let model = Arc::clone(&self.model);
        let pairs = tokio::task::spawn_blocking(move || infer(rows, budget, &model))
            .await
            .map_err(error)??;
        let provenance = serde_json::to_value(NativeProvenance {
            model: &self.model,
            model_version: "funder-frozen-v2",
            weldrs_version: "0.2.2",
            runtime: NativeRuntime {
                library: "weldrs",
                adapter_version: 1,
                distance_engine: DistanceEngine::WeldrsSimdUtf8Bytes,
            },
            calibrated: false,
        })
        .map_err(error)?;
        ScoredPairs::checked(pairs, provenance, input)
    }
}

fn infer(
    mut rows: Vec<ComparisonRow>,
    budget: usize,
    model: &NativeModel,
) -> Result<Vec<ScoredPair>, EntityIngestionError> {
    rows.sort_by(|a, b| a.key.cmp(&b.key));
    let candidates = bounded_candidates(&rows, &model.blocking, budget)?;
    let mut pairs = Vec::new();
    let mut batch = Vec::with_capacity(4096);
    for candidate in candidates {
        batch.push(candidate);
        if batch.len() == 4096 {
            pairs.extend(score_batch(&rows, &batch, model)?);
            batch.clear();
        }
    }
    if !batch.is_empty() {
        pairs.extend(score_batch(&rows, &batch, model)?);
    }
    Ok(pairs)
}

fn score_batch(
    rows: &[ComparisonRow],
    batch: &[Candidate],
    model: &NativeModel,
) -> Result<Vec<ScoredPair>, EntityIngestionError> {
    let left = batch
        .iter()
        .map(|pair| &rows[pair.left])
        .collect::<Vec<_>>();
    let right = batch
        .iter()
        .map(|pair| &rows[pair.right])
        .collect::<Vec<_>>();
    let frame = df!(
        "key_l" => left.iter().map(|r| r.key.as_str()).collect::<Vec<_>>(),
        "key_r" => right.iter().map(|r| r.key.as_str()).collect::<Vec<_>>(),
        "name_l" => left.iter().map(|r| r.name.as_str()).collect::<Vec<_>>(),
        "name_r" => right.iter().map(|r| r.name.as_str()).collect::<Vec<_>>(),
        "address_l" => left.iter().map(|r| r.address.as_deref()).collect::<Vec<_>>(),
        "address_r" => right.iter().map(|r| r.address.as_deref()).collect::<Vec<_>>()
    )
    .map_err(error)?;
    let vectors =
        compute_comparison_vectors(frame.lazy(), &model.comparisons, "gamma_").map_err(error)?;
    let vectors = match model.missing_address {
        MissingAddressPolicy::EitherMissingIsNeutral => vectors.with_column(
            when(col("address_l").is_null().or(col("address_r").is_null()))
                .then(lit(-1i8))
                .otherwise(col("gamma_address"))
                .alias("gamma_address"),
        ),
    };
    let output = predict_direct(
        vectors.collect().map_err(error)?,
        &model.comparisons,
        model.prior,
        "gamma_",
        "bf_",
        None,
        None,
    )
    .map_err(error)?;
    if output.height() != batch.len() {
        return Err(error("native prediction changed candidate count"));
    }
    let keys_l = output
        .column("key_l")
        .map_err(error)?
        .str()
        .map_err(error)?;
    let keys_r = output
        .column("key_r")
        .map_err(error)?
        .str()
        .map_err(error)?;
    let probabilities = output
        .column("match_probability")
        .map_err(error)?
        .f64()
        .map_err(error)?;
    let names = output
        .column("gamma_name")
        .map_err(error)?
        .i8()
        .map_err(error)?;
    let addresses = output
        .column("gamma_address")
        .map_err(error)?
        .i8()
        .map_err(error)?;
    batch
        .iter()
        .enumerate()
        .map(|(i, pair)| {
            if keys_l.get(i) != Some(rows[pair.left].key.as_str())
                || keys_r.get(i) != Some(rows[pair.right].key.as_str())
            {
                return Err(error("native prediction changed candidate endpoints"));
            }
            Ok(ScoredPair {
                left: rows[pair.left].key.clone(),
                right: rows[pair.right].key.clone(),
                probability: probabilities
                    .get(i)
                    .ok_or_else(|| error("missing prediction probability"))?,
                name_level: i32::from(
                    names
                        .get(i)
                        .ok_or_else(|| error("missing name comparison"))?,
                ),
                address_level: i32::from(
                    addresses
                        .get(i)
                        .ok_or_else(|| error("missing address comparison"))?,
                ),
            })
        })
        .collect()
}
use super::{ComparisonRow, EntityIngestionError, error};
use serde::Serialize;
use std::collections::{BTreeMap, BTreeSet};

#[derive(Clone, Copy, Serialize)]
pub(super) enum CandidateRule {
    ExactName,
    ExactAddress,
    NamePrefix {
        characters: usize,
    },
    InitialSurname {
        excluded_left_suffixes: &'static [&'static str],
        surname_prefix_characters: usize,
    },
    SharedBlockingKey,
}
impl CandidateRule {
    pub(super) const ALL: [Self; 5] = [
        Self::ExactName,
        Self::ExactAddress,
        Self::NamePrefix { characters: 3 },
        Self::InitialSurname {
            surname_prefix_characters: 2,
            excluded_left_suffixes: &["limited", "ltd", "plc", "llp", "company", "inc", "and"],
        },
        Self::SharedBlockingKey,
    ];
    fn keys(self, row: &ComparisonRow) -> BTreeSet<String> {
        match self {
            Self::ExactName => BTreeSet::from([row.name.clone()]),
            Self::ExactAddress => row.address.iter().cloned().collect(),
            Self::NamePrefix { characters } => {
                BTreeSet::from([row.name.chars().take(characters).collect()])
            }
            Self::InitialSurname {
                surname_prefix_characters,
                ..
            } => BTreeSet::from([format!(
                "{}\0{}",
                row.name.chars().take(1).collect::<String>(),
                suffix(&row.name)
                    .chars()
                    .take(surname_prefix_characters)
                    .collect::<String>()
            )]),
            Self::SharedBlockingKey => row.blocking_keys.iter().cloned().collect(),
        }
    }
    fn accepts(self, left: &ComparisonRow) -> bool {
        match self {
            Self::InitialSurname {
                excluded_left_suffixes,
                ..
            } => !excluded_left_suffixes.contains(&suffix(&left.name)),
            Self::ExactName
            | Self::ExactAddress
            | Self::NamePrefix { .. }
            | Self::SharedBlockingKey => true,
        }
    }
}
fn suffix(name: &str) -> &str {
    let start = name
        .bytes()
        .rposition(|b| !b.is_ascii_lowercase())
        .map_or(0, |i| i + 1);
    &name[start..]
}

#[derive(Clone, Copy, Eq, PartialEq, Ord, PartialOrd, Debug)]
pub(super) struct Candidate {
    pub(super) left: usize,
    pub(super) right: usize,
}
impl Candidate {
    fn new(a: usize, b: usize) -> Option<Self> {
        (a != b).then_some(Self {
            left: a.min(b),
            right: a.max(b),
        })
    }
}
#[derive(Default)]
struct Posting {
    all: Vec<usize>,
    unresolved: Vec<usize>,
}
struct CandidateSet {
    pairs: BTreeSet<Candidate>,
    budget: usize,
}
impl CandidateSet {
    fn insert(&mut self, pair: Candidate) -> Result<(), EntityIngestionError> {
        if self.pairs.contains(&pair) {
            return Ok(());
        }
        if self.pairs.len() == self.budget {
            return Err(error(format!(
                "candidate count exceeds budget {}",
                self.budget
            )));
        }
        self.pairs.insert(pair);
        Ok(())
    }
}

pub(super) fn bounded_candidates(
    rows: &[ComparisonRow],
    rules: &[CandidateRule],
    budget: usize,
) -> Result<BTreeSet<Candidate>, EntityIngestionError> {
    let mut candidates = CandidateSet {
        pairs: BTreeSet::new(),
        budget,
    };
    for &rule in rules {
        let mut index = BTreeMap::<String, Posting>::new();
        for (i, row) in rows.iter().enumerate() {
            for key in rule.keys(row) {
                let posting = index.entry(key).or_default();
                posting.all.push(i);
                if row.needs_resolution {
                    posting.unresolved.push(i);
                }
            }
        }
        for posting in index.values() {
            for &unresolved in &posting.unresolved {
                for &other in &posting.all {
                    if rows[other].needs_resolution && other < unresolved {
                        continue;
                    }
                    if let Some(pair) = Candidate::new(unresolved, other) {
                        if rule.accepts(&rows[pair.left]) {
                            candidates.insert(pair)?;
                        }
                    }
                }
            }
        }
    }
    Ok(candidates.pairs)
}

#[cfg(test)]
mod tests {
    use super::*;
    fn row(i: usize, unresolved: bool) -> ComparisonRow {
        ComparisonRow {
            key: format!("{i:08}"),
            name: "shared name".into(),
            address: None,
            blocking_keys: vec!["same".into(), "same".into()],
            needs_resolution: unresolved,
        }
    }
    #[test]
    fn duplicate_rules_and_tokens_preserve_exact_budget() {
        let rows = [row(0, true), row(1, true), row(2, true)];
        assert_eq!(
            bounded_candidates(&rows, &CandidateRule::ALL, 3)
                .unwrap()
                .len(),
            3
        );
        assert!(bounded_candidates(&rows, &CandidateRule::ALL, 2).is_err());
        assert!(bounded_candidates(&rows, &CandidateRule::ALL, 0).is_err());
    }
    #[test]
    fn anchored_groups_have_no_candidates() {
        let rows = (0..10_000).map(|i| row(i, false)).collect::<Vec<_>>();
        assert!(
            bounded_candidates(&rows, &CandidateRule::ALL, 0)
                .unwrap()
                .is_empty()
        );
    }
    #[test]
    fn refusal_does_not_insert_an_excess_pair() {
        let mut candidates = CandidateSet {
            pairs: BTreeSet::new(),
            budget: 2,
        };
        candidates.insert(Candidate::new(0, 1).unwrap()).unwrap();
        candidates.insert(Candidate::new(0, 2).unwrap()).unwrap();
        assert!(candidates.insert(Candidate::new(0, 3).unwrap()).is_err());
        assert_eq!(candidates.pairs.len(), 2);
        let mut rows = (0..10_000).map(|i| row(i, false)).collect::<Vec<_>>();
        rows[0].needs_resolution = true;
        assert!(bounded_candidates(&rows, &CandidateRule::ALL, 2).is_err());
    }
    #[test]
    fn initial_surname_exclusion_uses_only_the_canonical_left() {
        let rule = [CandidateRule::InitialSurname {
            excluded_left_suffixes: &["limited"],
            surname_prefix_characters: 2,
        }];
        let mut left = row(0, true);
        let mut right = row(1, true);
        left.name = "alpha limited".into();
        right.name = "another lime".into();
        assert!(
            bounded_candidates(&[left.clone(), right.clone()], &rule, 1)
                .unwrap()
                .is_empty()
        );
        left.name = "another lime".into();
        right.name = "alpha limited".into();
        assert_eq!(
            bounded_candidates(&[left, right], &rule, 1).unwrap().len(),
            1
        );
    }

    #[test]
    fn unicode_prefix_empty_suffix_and_present_empty_address_are_keys() {
        let mut left = row(0, true);
        let mut right = row(1, false);
        left.name = "é🙂a left".into();
        right.name = "é🙂a right".into();
        assert_eq!(
            bounded_candidates(
                &[left.clone(), right.clone()],
                &[CandidateRule::NamePrefix { characters: 3 }],
                1
            )
            .unwrap()
            .len(),
            1
        );
        left.name = "a!".into();
        right.name = "a?".into();
        assert_eq!(
            bounded_candidates(&[left.clone(), right.clone()], &[CandidateRule::ALL[3]], 1)
                .unwrap()
                .len(),
            1
        );
        left.address = Some(String::new());
        right.address = Some(String::new());
        assert_eq!(
            bounded_candidates(
                &[left.clone(), right.clone()],
                &[CandidateRule::ExactAddress],
                1
            )
            .unwrap()
            .len(),
            1
        );
        right.address = None;
        assert!(
            bounded_candidates(&[left, right], &[CandidateRule::ExactAddress], 0)
                .unwrap()
                .is_empty()
        );
    }
}

