        for (a, b) in &pairs {
            for threshold in 0..=10 {
                let expected = strsim::levenshtein(a, b) as u32 <= threshold;
                let got = levenshtein_within(a, b, threshold);
                assert_eq!(
                    got, expected,
                    "levenshtein_within({a:?}, {b:?}, {threshold}) = {got}, expected {expected}"
